## 🛠️ Testing Skeleton

All tests live under `/tests`. Here’s how one would look:

```ts
// tests/unit/service.shipment.test.ts
import { ShipmentService } from '@/services/shipment.service';
import { mockDeep, DeepMockProxy } from 'jest-mock-extended';
import { ShipmentRepository } from '@/repositories/shipment.repo';

describe('ShipmentService', () => {
  let svc: ShipmentService;
  let repoStub: DeepMockProxy<ShipmentRepository>;

  beforeEach(() => {
    repoStub = mockDeep<ShipmentRepository>();
    svc = new ShipmentService(repoStub);
  });

  it('creates a shipment successfully', async () => {
    const dto = {
      origin: 'NYC',
      destination: 'LA',
      weightKg: 1200,
      scheduledDate: new Date(),
    };
    const result = await svc.create(dto);
    expect(result.id).toBeDefined();
    expect(repoStub.save).toHaveBeenCalledTimes(1);
  });
});
```

Add similar suites for services, repos, and integration tests hitting the actual API endpoints.

